using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class MarinaContainerPlacementRepair{static MarinaContainerPlacementRepair(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("MarinaContainerPlacementRepair.request"))return;File.Delete("MarinaContainerPlacementRepair.request");const string D="Assets/Scenes/Oasis/YachtPortAtlas";var r=PrefabUtility.LoadPrefabContents(D+"/Marina Existing City Props Features.prefab");foreach(var t in r.transform.Cast<Transform>().Where(t=>t.name.StartsWith("Detailed")&&t.name.ToLower().Contains("container")).ToArray())Object.DestroyImmediate(t.gameObject);int i=0;foreach(string color in new[]{"Blue","Red","Ivory"}){string path=D+"/Detailed "+color+" Container.prefab";var p=PrefabUtility.LoadPrefabContents(path);p.GetComponent<MeshFilter>().sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(D+"/Meshes/Mobile detailed "+color+" freight container.asset");var lod=p.GetComponent<LODGroup>();Object.DestroyImmediate(lod);PrefabUtility.SaveAsPrefabAsset(p,path);PrefabUtility.UnloadPrefabContents(p);var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),r.transform);g.transform.localPosition=new Vector3(-23+i++*10,AssetDatabase.LoadAssetAtPath<Mesh>(D+"/Meshes/Grand Ground Level Yacht Yard.asset").vertices.Max(v=>v.y),22);g.SetActive(true);}PrefabUtility.SaveAsPrefabAsset(r,D+"/Marina Existing City Props Features.prefab");PrefabUtility.UnloadPrefabContents(r);AssetDatabase.SaveAssets();}}
